function check(input, actual, expected) {
  const s = input[0];
  if (typeof actual !== 'string' || typeof expected !== 'string' || actual.length !== expected.length) return false;
  let pos = 0;
  let valid = true;
  // Decode a run of letters and blocks, stopping at a closing bracket or the end.
  const decode = () => {
    let out = '';
    while (valid && pos < actual.length && actual[pos] !== ']') {
      const ch = actual[pos];
      if (ch >= 'a' && ch <= 'z') { out += ch; pos++; }
      else if (ch >= '1' && ch <= '9') {
        const start = pos;
        while (pos < actual.length && actual[pos] >= '0' && actual[pos] <= '9') pos++;
        const count = Number(actual.slice(start, pos));
        if (actual[pos] !== '[') { valid = false; break; }
        pos++;
        const inner = decode();
        if (!valid || actual[pos] !== ']') { valid = false; break; }
        pos++;
        // The block must decode to text that fits in s and must be strictly shorter than that text.
        if (count * inner.length > s.length || pos - start >= count * inner.length) { valid = false; break; }
        out += inner.repeat(count);
      } else { valid = false; break; }
      if (out.length > s.length) valid = false;
    }
    return out;
  };
  const decoded = decode();
  return valid && pos === actual.length && decoded === s;
}

