function encode(s) {
  const n = s.length;
  const dp = Array.from({ length: n }, () => new Array(n).fill(''));
  for (let length = 1; length <= n; length++) {
    for (let i = 0; i + length <= n; i++) {
      const j = i + length - 1;
      const sub = s.slice(i, j + 1);
      dp[i][j] = sub;
      if (length < 5) continue;
      for (let split = i; split < j; split++) {
        const joined = dp[i][split] + dp[split + 1][j];
        if (joined.length < dp[i][j].length) {
          dp[i][j] = joined;
        }
      }
      const period = (sub + sub).indexOf(sub, 1);
      if (period < length) {
        const packed = length / period + '[' + dp[i][i + period - 1] + ']';
        if (packed.length < dp[i][j].length) {
          dp[i][j] = packed;
        }
      }
    }
  }
  return dp[0][n - 1];
}

