function encode(s) {
  // Top-down search over every way to write a piece: as is, cut in two, or as count[unit] for any unit that tiles it.
  const memo = new Map();
  const best = text => {
    if (memo.has(text)) return memo.get(text);
    let answer = text;
    for (let cut = 1; cut < text.length; cut++) {
      const option = best(text.slice(0, cut)) + best(text.slice(cut));
      if (option.length < answer.length) answer = option;
    }
    for (let size = 1; size < text.length; size++) {
      if (text.length % size !== 0) continue;
      const unit = text.slice(0, size);
      if (unit.repeat(text.length / size) !== text) continue;
      const option = `${text.length / size}[${best(unit)}]`;
      if (option.length < answer.length) answer = option;
    }
    memo.set(text, answer);
    return answer;
  };
  return best(s);
}

