function generate(rand, size) {
  const target = size === 'large' ? 150 : 1 + Math.floor(rand() * 16);
  const alphabet = 'abc'.slice(0, 1 + Math.floor(rand() * 3));
  const letters = count => {
    let text = '';
    for (let i = 0; i < count; i++) text += alphabet[Math.floor(rand() * alphabet.length)];
    return text;
  };
  // Build from repeated (and sometimes nested) units so that real savings exist.
  const piece = (limit, depth) => {
    if (depth >= 3 || limit < 2 || rand() < 0.35) return letters(1 + Math.floor(rand() * Math.min(3, limit)));
    const unit = piece(Math.max(1, Math.floor(limit / 2)), depth + 1);
    const most = Math.max(2, Math.floor(limit / unit.length));
    return unit.repeat(2 + Math.floor(rand() * (most - 1)));
  };
  let s = '';
  while (s.length < target) s += piece(target - s.length, 0);
  return [s.slice(0, target)];
}
